{
  "name": "Jubilee 模块化自动换工具运动平台",
  "name_en": "Jubilee modular tool-changing motion platform",
  "manufacturer": "Machine Agency",
  "description": "Jubilee 是一台用于实验室自动化的台式多轴运动平台，支持自动换工具与甲板式工作区配置。它可在 X/Y/Z/U 等轴上精确移动，并配合移液、注射或其他末端工具执行定位、取放工具、装载 labware、样品转移等任务，适用于通用实验室自动化和液体处理流程。",
  "description_en": "Jubilee is a benchtop multi-axis motion platform for laboratory automation with automatic tool changing and deck-based workspace configuration. It can move precisely along axes such as X/Y/Z/U and work with pipetting, syringe, or other end tools for positioning, tool pickup and parking, labware placement, and sample-handling tasks in general lab automation workflows.",
  "tag_hints": [
    "lab automation",
    "tool changing",
    "multi-axis motion control",
    "deck-based workflow",
    "liquid handling",
    "sample positioning",
    "G-code control"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 Jubilee 运动平台。",
      "description_en": "Connect to the Jubilee motion platform."
    },
    {
      "action_name": "auto-active_tool_index",
      "description": "获取/设置当前活动工具编号。",
      "description_en": "Get/set the active tool index."
    },
    {
      "action_name": "auto-load_deck",
      "description": "加载甲板配置。",
      "description_en": "Load a deck configuration."
    },
    {
      "action_name": "auto-split_response_objects",
      "description": "拆分设备返回的多行响应消息。",
      "description_en": "Split multi-line response messages returned by the device."
    },
    {
      "action_name": "auto-gcode",
      "description": "向运动平台发送 G-code 指令。",
      "description_en": "Send a G-code command to the motion platform."
    },
    {
      "action_name": "auto-delay_time",
      "description": "计算下一次通信请求的延迟时间。",
      "description_en": "Calculate the delay time before the next communication request."
    },
    {
      "action_name": "auto-push_machine_state",
      "description": "保存当前机器状态。",
      "description_en": "Save the current machine state."
    },
    {
      "action_name": "auto-pop_machine_state",
      "description": "恢复之前保存的机器状态。",
      "description_en": "Restore a previously saved machine state."
    },
    {
      "action_name": "auto-download_file",
      "description": "从机器控制器下载文件。",
      "description_en": "Download a file from the machine controller."
    },
    {
      "action_name": "auto-reset",
      "description": "软件复位机器控制器。",
      "description_en": "Perform a software reset of the machine controller."
    },
    {
      "action_name": "auto-home_all",
      "description": "使所有轴回零。",
      "description_en": "Home all axes."
    },
    {
      "action_name": "auto-home_xyu",
      "description": "使 X、Y、U 轴回零。",
      "description_en": "Home the X, Y, and U axes."
    },
    {
      "action_name": "auto-home_x",
      "description": "使 X 轴回零。",
      "description_en": "Home the X axis."
    },
    {
      "action_name": "auto-home_y",
      "description": "使 Y 轴回零。",
      "description_en": "Home the Y axis."
    },
    {
      "action_name": "auto-home_u",
      "description": "使 U 轴回零。",
      "description_en": "Home the U axis."
    },
    {
      "action_name": "auto-home_v",
      "description": "使 V 轴回零。",
      "description_en": "Home the V axis."
    },
    {
      "action_name": "auto-home_z",
      "description": "使 Z 轴回零。",
      "description_en": "Home the Z axis."
    },
    {
      "action_name": "auto-home_e",
      "description": "使 E 轴回零。",
      "description_en": "Home the E axis."
    },
    {
      "action_name": "auto-home_in_place",
      "description": "将当前位置定义为一个或多个轴的零点。",
      "description_en": "Define the current position as zero for one or more axes."
    },
    {
      "action_name": "auto-set_tool_offset",
      "description": "定义工具的位置偏移。",
      "description_en": "Define the positional offset of a tool."
    },
    {
      "action_name": "auto-move_to",
      "description": "移动到绝对位置。",
      "description_en": "Move to an absolute position."
    },
    {
      "action_name": "auto-move",
      "description": "按相对位移移动。",
      "description_en": "Move by a relative displacement."
    },
    {
      "action_name": "auto-dwell",
      "description": "暂停指定时间。",
      "description_en": "Pause for a specified time."
    },
    {
      "action_name": "auto-safe_z_movement",
      "description": "将 Z 轴移动到安全高度。",
      "description_en": "Move the Z axis to a safe height."
    },
    {
      "action_name": "auto-load_tool",
      "description": "在平台上加载并注册工具。",
      "description_en": "Load and register a tool on the platform."
    },
    {
      "action_name": "auto-reload_tool",
      "description": "重新加载并更新已注册工具。",
      "description_en": "Reload and update a previously registered tool."
    },
    {
      "action_name": "auto-pickup_tool",
      "description": "拾取指定工具。",
      "description_en": "Pick up the specified tool."
    },
    {
      "action_name": "auto-park_tool",
      "description": "停放当前工具。",
      "description_en": "Park the current tool."
    },
    {
      "action_name": "auto-load_labware",
      "description": "将 labware 配置加载到甲板槽位。",
      "description_en": "Load a labware definition into a deck slot."
    },
    {
      "action_name": "auto-tool_lock",
      "description": "锁定工具机构。",
      "description_en": "Engage the tool lock."
    },
    {
      "action_name": "auto-tool_unlock",
      "description": "解锁工具机构。",
      "description_en": "Release the tool lock."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与运动平台的连接。",
      "description_en": "Disconnect from the motion platform."
    },
    {
      "action_name": "auto-configured_axes",
      "description": "获取已配置的轴。",
      "description_en": "Get the configured axes."
    },
    {
      "action_name": "auto-configured_tools",
      "description": "获取已配置的工具。",
      "description_en": "Get the configured tools."
    },
    {
      "action_name": "auto-tool_z_offsets",
      "description": "获取各工具的 Z 轴偏移。",
      "description_en": "Get the Z offsets of the tools."
    },
    {
      "action_name": "auto-axis_limits",
      "description": "获取各轴运动范围限制。",
      "description_en": "Get the travel limits of the axes."
    },
    {
      "action_name": "auto-position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    }
  ]
}

